def orfs_from_atg(s,label):
    out=[]
    for f in range(3):
        for i in range(f, len(s)-2, 3):
            if s[i:i+3]=='ATG':
                j=i
                while j < len(s)-2 and s[j:j+3] not in stops:
                    j+=3
